import{_ as a,o as t,c as n,a2 as s}from"./chunks/framework.C-si7TFR.js";const u=JSON.parse('{"title":"IOLinker Agent智能体","description":"IOLinker Agent智能体（AI Agent） 是一个能够感知环境、自主分析、做出决策并执行行动，以达成特定目标。它支持配置MCP工具，拓展Agent与外部环境的交互。同时，可开启记忆功能，支持连贯对话。","frontmatter":{"title":"IOLinker Agent智能体","description":"IOLinker Agent智能体（AI Agent） 是一个能够感知环境、自主分析、做出决策并执行行动，以达成特定目标。它支持配置MCP工具，拓展Agent与外部环境的交互。同时，可开启记忆功能，支持连贯对话。","meta":[{"name":"keywords","content":"Agent 智能体, AI Agent, ReAct框架, MCP Server工具, Agent记忆, 推理, 大模型, 低代码, AI工作流, 流程引擎"}]},"headers":[],"relativePath":"zh/iolinker_agent.md","filePath":"zh/iolinker_agent.md"}'),o={name:"zh/iolinker_agent.md"};function i(l,e,p,r,c,d){return t(),n("div",null,[...e[0]||(e[0]=[s(`<h2 id="iolinker-agent智能体" tabindex="-1">IOLinker Agent智能体 <a class="header-anchor" href="#iolinker-agent智能体" aria-label="Permalink to &quot;IOLinker Agent智能体&quot;">​</a></h2><h3 id="创建llm凭据" tabindex="-1">创建LLM凭据 <a class="header-anchor" href="#创建llm凭据" aria-label="Permalink to &quot;创建LLM凭据&quot;">​</a></h3><p>在【应用开发】&gt;【凭据管理】创建一个LLM API密钥凭据，目前LLM大模型支持包括：Deepseek、豆包、Kimi、OpenAI、千问以及开源的Ollama。</p><blockquote><p>原截图含凭据、令牌或应用标识，已停止公开。请在对应平台自行创建秘密并填入本地配置。</p></blockquote><h3 id="配置iolinker-agent" tabindex="-1">配置IOLinker Agent <a class="header-anchor" href="#配置iolinker-agent" aria-label="Permalink to &quot;配置IOLinker Agent&quot;">​</a></h3><p>这里可以结合Telegram触发器一起使用，可以通过Telegram发送消息给Agent，并通过Telegram消息发送APP反馈Agent的处理结果给用户。</p><blockquote><p>历史界面图片在复核并重拍前不展示，请按当前界面核对操作。</p></blockquote><h3 id="测试-iolinker-agent" tabindex="-1">测试 IOLinker Agent <a class="header-anchor" href="#测试-iolinker-agent" aria-label="Permalink to &quot;测试 IOLinker Agent&quot;">​</a></h3><p>我们打开配置的Telegram机器人，可以直接跟机器人互动。例如询问它<code>能做什么</code>，它会基于当前的环境和能调用的外部工具给你一个反馈消息。机器人的每一次回复都是在<code>执行记录</code>列表产生一个执行记录。</p><blockquote><p>历史界面图片在复核并重拍前不展示，请按当前界面核对操作。</p></blockquote><blockquote><p>历史界面图片在复核并重拍前不展示，请按当前界面核对操作。</p></blockquote><p>双击APP可以查看当前APP的输出结果。</p><blockquote><p>历史界面图片在复核并重拍前不展示，请按当前界面核对操作。</p></blockquote><p>右键点击可以选择查看对话记录：</p><blockquote><p>历史界面图片在复核并重拍前不展示，请按当前界面核对操作。</p></blockquote><blockquote><p>历史界面图片在复核并重拍前不展示，请按当前界面核对操作。</p></blockquote><h3 id="工具调用" tabindex="-1">工具调用 <a class="header-anchor" href="#工具调用" aria-label="Permalink to &quot;工具调用&quot;">​</a></h3><p>当我们想要计算时，Agent发现有对应的MCP工具，它会自动规划请求的参数并发起调用。</p><blockquote><p>历史界面图片在复核并重拍前不展示，请按当前界面核对操作。</p></blockquote><p>由于Agent调用了MCP工具，所以这里除了Agent的执行记录，还有一个mcp的执行记录。</p><blockquote><p>历史界面图片在复核并重拍前不展示，请按当前界面核对操作。</p></blockquote><p>我们可以在执行详情查看到Agent跟用户的完整交互过程，也可以看到它是如何思考和调用工具的。</p><blockquote><p>历史界面图片在复核并重拍前不展示，请按当前界面核对操作。</p></blockquote><h2 id="输入" tabindex="-1">输入 <a class="header-anchor" href="#输入" aria-label="Permalink to &quot;输入&quot;">​</a></h2><blockquote><p>历史界面图片在复核并重拍前不展示，请按当前界面核对操作。</p></blockquote><h3 id="api密钥" tabindex="-1">API密钥 <a class="header-anchor" href="#api密钥" aria-label="Permalink to &quot;API密钥&quot;">​</a></h3><p>可以选择在【应用开发】&gt;【凭据管理】创建的LLM API密钥。</p><h3 id="模型" tabindex="-1">模型 <a class="header-anchor" href="#模型" aria-label="Permalink to &quot;模型&quot;">​</a></h3><p>系统会根据当前选择的LLM厂商平台类型返回支持的模型列表，如果有模型不在返回的下拉列表中，可以直接在编辑框输入。</p><h3 id="框架" tabindex="-1">框架 <a class="header-anchor" href="#框架" aria-label="Permalink to &quot;框架&quot;">​</a></h3><p><strong>ReAct</strong> 是一个让AI智能体（Agent）通过<strong>推理</strong>和<strong>行动</strong>来解决问题的框架。它的核心思想是：<strong>不让AI直接给出答案，而是让它像人类一样“思考-行动-再思考”的循环过程来完成任务。</strong></p><p>ReAct的工作流程是一个典型的循环，可以概括为以下三个步骤，并不断重复直到问题解决：</p><p><strong>思考 → 行动 → 观察</strong></p><ol><li><strong>思考</strong>AI分析当前的问题和已经获得的信息。<strong>关键：AI必须用文字形式写出它的思考过程。</strong> 例如：“用户问的是今天的天气，但我不知道当前日期和位置。我需要先获取当前日期，然后询问用户的位置。”这一步将AI的“内心戏”外化，使我们能追踪它的逻辑，也帮助它自己理清思路。</li><li><strong>行动</strong>基于上一步的思考，AI决定执行一个具体的动作。动作通常是通过调用一个<strong>工具</strong>来完成。例如：<code>Search[“今日日期”]</code>（调用搜索工具）<code>Calculator[“(25 * 4) / 2”]</code>（调用计算器工具）<code>BrowseWebsite[“某个URL”]</code>（调用浏览器工具）甚至可以直接向用户提问：<code>AskUser[“请问您所在的城市是？”]</code></li><li><strong>观察</strong>行动执行后，环境（或工具）会返回一个结果。AI接收并记录这个结果。例如，搜索“今日日期”后，观察到结果是“2024年5月20日”。这个观察结果成为了解决问题的新信息。</li></ol><p>然后，循环继续：AI基于所有现有信息（原始问题 + 新观察到的结果）进行<strong>新一轮的思考</strong>，决定下一步行动，如此往复，直到它认为有足够的信息可以给出最终答案。</p><h3 id="最大循环次数" tabindex="-1">最大循环次数 <a class="header-anchor" href="#最大循环次数" aria-label="Permalink to &quot;最大循环次数&quot;">​</a></h3><p>设置Agent基于ReAct框架循环的最大次数，即限制<code>思考 → 行动 → 观察</code>循环次数，避免Agent陷入无尽的死循环中。</p><blockquote><p>历史界面图片在复核并重拍前不展示，请按当前界面核对操作。</p></blockquote><h3 id="系统消息" tabindex="-1">系统消息 <a class="header-anchor" href="#系统消息" aria-label="Permalink to &quot;系统消息&quot;">​</a></h3><p>定义AI Agent的“人设”、角色、行为准则和对话边界。</p><h3 id="用户消息" tabindex="-1">用户消息 <a class="header-anchor" href="#用户消息" aria-label="Permalink to &quot;用户消息&quot;">​</a></h3><p>给Agent下发具体的任务指令。</p><h3 id="输出格式" tabindex="-1">输出格式 <a class="header-anchor" href="#输出格式" aria-label="Permalink to &quot;输出格式&quot;">​</a></h3><p>设置Agent输出的字符串格式。</p><ul><li><p>Raw(XML)。这个是Agent原生的输出格式，在字符串中会带有一些xml的内容，记录Agent的思考过程以及一些工具调用。</p></li><li><p>Markdown。将上面的xml标记转换成markdown格式。</p></li></ul><h3 id="逐轮输出" tabindex="-1">逐轮输出 <a class="header-anchor" href="#逐轮输出" aria-label="Permalink to &quot;逐轮输出&quot;">​</a></h3><p>启用后，智能体的思考过程将在每次ReAct迭代中输出。如果启用Telegram触发器，则发送telegram消息。</p><blockquote><p>历史界面图片在复核并重拍前不展示，请按当前界面核对操作。</p></blockquote><h3 id="mcp-工具" tabindex="-1">MCP 工具 <a class="header-anchor" href="#mcp-工具" aria-label="Permalink to &quot;MCP 工具&quot;">​</a></h3><p>这里可以选择在工作流列表中的<a href="https://doc.iolinker.com/zh/mcp.html" target="_blank" rel="noreferrer">MCP 触发器</a>创建的MCP Server工具。勾选后，Agent会在分析时根据任务选择对应的工具调用。</p><h3 id="内置工具" tabindex="-1">内置工具 <a class="header-anchor" href="#内置工具" aria-label="Permalink to &quot;内置工具&quot;">​</a></h3><p>这里是系统自身自带的工具，用户可以根据实际需要勾选。</p><ul><li><p>End Session。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>这个是结束当前会话或者发起新的会话。当用户对Agent下发诸如结束、重新开始会话等明显的结束意图时，Agent会认为用户想要结束当前会话或发起新的会话。</span></span></code></pre></div><p>注意：一个会话会涉及到多个对话记录，可能涉及多次的工作流执行。</p></li><li><p>Ask Followup Question</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Agent向用户提问以收集完成任务所需的其他信息。当遇到歧义、需要澄清或需要更多细节才能有效推进时，Agent会使用此工具。它支持与用户直接沟通，从而实现交互式问题解决。</span></span></code></pre></div></li><li><p>Attempt Completion</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Agent每次使用工具后，用户都会反馈工具使用结果，即成功或失败，以及失败原因。收到工具使用结果并确认任务完成后，Agent会使用此工具向用户展示工作成果。</span></span></code></pre></div></li><li><p>Use MCP Tool</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Agent会根据实际情况请求使用已连接的 MCP 服务器提供的工具。每个 MCP 服务器可以提供多个功能各异的工具。</span></span></code></pre></div></li><li><p>Web Fetch</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>当Agent认为需要检索和分析网页内容时，会使用此工具。</span></span></code></pre></div></li><li><p>Execute Command</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>当Agent认为需要执行系统操作或运行特定命令来完成用户任务中的任何步骤时，会使用此功能在系统上执行 CLI 命令。</span></span></code></pre></div></li><li><p>Read File</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>当Agent认为需要检查一个未知内容的现有文件时，例如分析代码、查看文本文件或从配置文件中提取信息，会使用此功能请求读取指定路径下文件的内容。</span></span></code></pre></div></li><li><p>Write To File</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>请求将内容写入指定路径的文件。如果文件已存在，则会用提供的内容覆盖它。如果文件不存在，则会创建该文件。此工具会自动创建写入文件所需的任何目录。</span></span></code></pre></div></li><li><p>Search Files</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>请求对指定目录中的文件执行正则表达式搜索，并提供包含上下文信息的结果。</span></span></code></pre></div></li></ul><blockquote><p>历史界面图片在复核并重拍前不展示，请按当前界面核对操作。</p></blockquote><h3 id="历史对话" tabindex="-1">历史对话 <a class="header-anchor" href="#历史对话" aria-label="Permalink to &quot;历史对话&quot;">​</a></h3><p>开启历史对话功能后，Agent可以实现记忆功能，实现连贯对话。</p><ul><li>对话轮数：加载最近n轮的历史对话记录，最大可加载1000轮对话。</li><li>对话时间：加载最近n分钟前的历史对话记录，最大可加载10天内的对话。</li></ul><h2 id="输出" tabindex="-1">输出 <a class="header-anchor" href="#输出" aria-label="Permalink to &quot;输出&quot;">​</a></h2><ul><li>content：Agent返回的结果</li><li>isSessionFinish：表示当前会话是否结束。如果未开启历史对话功能，则该值已知为true，表示对话是一次性的。如果开启了历史对话功能，由于会话涉及多轮，中间运行结果该值为false，只有用于明显发出结束意图时，Agent会调用<code>End Session</code>工具结束会话，并设置该值为true</li><li>sessionId：会话ID，如果开启历史对话，则中间产生的sessionId是相同的，表示是同一个会话。</li><li>userId：会话用户。</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        &quot;content&quot;: &quot;....&quot;,</span></span>
<span class="line"><span>        &quot;isSessionFinish&quot;: true,</span></span>
<span class="line"><span>        &quot;runId&quot;: &quot;379709981500375040&quot;,</span></span>
<span class="line"><span>        &quot;sessionId&quot;: &quot;e4da7671-aa01-41f3-9b51-826ea0955f6c&quot;,</span></span>
<span class="line"><span>        &quot;token&quot;: 0,</span></span>
<span class="line"><span>        &quot;userId&quot;: &quot;iolinker&quot;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>]</span></span></code></pre></div>`,60)])])}const g=a(o,[["render",i]]);export{u as __pageData,g as default};
